out.recv:
//* The RECEIVE targets are deleted first: TSO RECEIVE refuses to
//* merge into an existing dataset, so without this the job would
//* run exactly once. SET MAXCC=0 keeps a first run, where none of
//* them exists yet, from failing on the DELETEs.
//*
//DELOLD  EXEC PGM=IDCAMS
//SYSPRINT DD  SYSOUT=*
//SYSIN    DD  *
  DELETE ABC.V1R2M0.LKLIB NONVSAM SCRATCH PURGE
  DELETE ABC.SAMPLIB NONVSAM SCRATCH PURGE
  SET MAXCC=0
/*
//*
//* p-1.2.0-load.xmit
//*   -> ABC.V1R2M0.LKLIB
//RECV1   EXEC PGM=IKJEFT01,DYNAMNBR=20
//SYSTSPRT DD  SYSOUT=*
//SYSTSIN  DD  *
  RECEIVE INDSN('CHANGE.ME.LKLIB') -
    DATASET('ABC.V1R2M0.LKLIB')
/*
//*
//* p-1.2.0-samplib.xmit
//*   -> ABC.SAMPLIB
//RECV2   EXEC PGM=IKJEFT01,DYNAMNBR=20
//SYSTSPRT DD  SYSOUT=*
//SYSTSIN  DD  *
  RECEIVE INDSN('CHANGE.ME.SAMPLIB') -
    DATASET('ABC.SAMPLIB')
/*

